619	    private async resolveAvailableLocalModels(modelId: string, intent: RoutingDecision['intent']) {
620	        const tags = await this.getLocalModelTags();
621	        const normalized = this.normalizeLocalModelName(modelId);
622	        if (tags.has(normalized)) {
