629	    private async getLocalModelTags(force = false): Promise<Set<string>> {
630	        const now = Date.now();
631	        if (!force && this.localModelTagCache && this.localModelTagCache.expiresAt > now) {
632	            return this.localModelTagCache.tags;
633	        }
634	
635	        const response = await this.axiosInstance.get(`${this.ollamaHost}/api/tags`, { timeout: 1500 });
636	        const tags = new Set<string>();
637	        for (const model of response.data?.models || []) {
638	            if (model?.name) tags.add(model.name);
639	            if (model?.model) tags.add(model.model);
640	        }
641	
642	        this.localModelTagCache = {
643	            tags,
644	            expiresAt: now + LOCAL_TAG_CACHE_TTL_MS
645	        };
646	
647	        return tags;
648	    }
