59	        const response = await client.chat.completions.create(requestBody as any);
60	
61	        return {
62	            content: response.choices[0].message.content,
63	            model: response.model,
64	            usage: response.usage,
65	            provider: config?.providerName || 'openai'
66	        };
67	    }
