75	        if (!apiKey) throw new Error('OPENAI_CLIENT_NOT_INITIALIZED');
76	        return this.createClient({
77	            apiKey,
78	            baseURL: config?.baseURL || process.env.OPENAI_BASE_URL
79	        });
80	    }
