287	    private async runChat(
288	        modelId: string,
289	        messages: any[],
290	        systemPrompt?: string,
291	        options: NeuralChatOptions = {}
292	    ): Promise<NeuralChatResponse> {
293	        const pingStatus = await this.ping();
294	        const lastUserMessage = this.extractLastUserMessage(messages);
295	        const decision = SmartRouter.route(lastUserMessage || modelId, {
296	            ...options,
297	            modelId,
298	            providerStatus: pingStatus
299	        });
300	        const requestedModel = modelId || decision.preferredModel;
301	        const retrievalContext = await this.buildVaultContext(
302	            lastUserMessage,
303	            options.retrievalProfile || decision.retrievalProfile,
304	            options.reasoningBudget || decision.reasoningBudget
305	        );
306	
307	        const contextSections = [systemPrompt || '', retrievalContext].filter(Boolean);
308	        const compression = promptCompression.compress(
309	            contextSections.join('\n\n'),
310	            options.compressionMode || decision.compressionMode
311	        );
312	        const finalSystemPrompt = compression.content;
313	
314	        let escalated = false;
315	        let fallbackCause: string | undefined;
316	        let lastError: Error | null = null;
317	        const allowLocal = options.allowLocal !== false;
318	        const allowCloud = options.allowCloud !== false;
319	
320	        for (const candidate of decision.fallbackChain) {
321	            const candidateModel = candidate || requestedModel;
322	            const runtime = this.getModelRuntime(candidateModel);
323	
324	            if (runtime === 'local' && !allowLocal) continue;
325	            if (runtime === 'cloud' && !allowCloud) continue;
326	
327	            try {
328	                if (runtime === 'local') {
329	                    const availableLocals = await this.resolveAvailableLocalModels(candidateModel, decision.intent);
330	                    if (availableLocals.length === 0) {
331	                        fallbackCause = `LOCAL_MODEL_UNAVAILABLE :: ${candidateModel}`;
332	                        continue;
333	                    }
334	
335	                    const primaryLocal = availableLocals[0];
336	                    const execution = (!fallbackCause && this.shouldUseReasoningLoop(decision, runtime))
337	                        ? await this.executeLocalReasoningLoop(primaryLocal, messages, finalSystemPrompt, decision)
338	                        : {
339	                            response: await this.executeOllamaChat(primaryLocal, messages, finalSystemPrompt),
340	                            shouldEscalate: false,
341	                            loopCount: 1
342	                        } as LoopExecutionResult;
343	
344	                    if (execution.shouldEscalate && allowCloud) {
345	                        escalated = true;
346	                        fallbackCause = execution.fallbackCause || 'LOCAL_LOW_CONFIDENCE';
347	                        continue;
348	                    }
349	
350	                    const response = this.decorateResponse(execution.response, {
351	                        runtime: 'local',
352	                        compression: compression.stats,
353	                        escalated,
354	                        loopCount: execution.loopCount,
355	                        decision,
356	                        contextInjected: !!retrievalContext
357	                    });
358	                    this.recordExecutionSnapshot(response, decision, fallbackCause);
359	                    return response;
360	                }
361	
362	                const providerType = this.getProviderType(candidateModel);
363	                if (!providerType || !this.isProviderAvailable(providerType, pingStatus)) {
364	                    fallbackCause = `PROVIDER_UNAVAILABLE :: ${candidateModel}`;
365	                    continue;
366	                }
367	
368	                const response = await this.executeNativeChat(
369	                    providerType,
370	                    candidateModel,
371	                    messages,
372	                    finalSystemPrompt,
373	                    options
374	                );
375	                const decorated = this.decorateResponse(response, {
376	                    runtime: 'cloud',
377	                    compression: compression.stats,
378	                    escalated,
379	                    loopCount: 1,
380	                    decision,
381	                    contextInjected: !!retrievalContext
382	                });
383	                this.recordExecutionSnapshot(decorated, decision, fallbackCause);
384	                return decorated;
385	            } catch (error: any) {
386	                lastError = error;
387	                fallbackCause = error.message;
388	                console.error(`⬡ NEURAL_FORGE_ATTEMPT_FAILED :: ${candidateModel} :: ${error.message}`);
389	
390	                const providerType = this.getProviderType(candidateModel);
391	                if (runtime === 'cloud' && providerType && this.shouldPenalizeProvider(error)) {
392	                    tokenGovernor.penalize(providerType);
393	                }
394	            }
395	        }
396	
397	        throw lastError || new Error(fallbackCause || `NO_AVAILABLE_RUNTIME :: ${requestedModel}`);
398	    }
