540	    private async executeLocalReasoningLoop(
541	        localModelName: string,
542	        messages: any[],
543	        finalSystemPrompt: string,
544	        decision: RoutingDecision
545	    ): Promise<LoopExecutionResult> {
546	        const draft = await this.executeOllamaChat(localModelName, messages, finalSystemPrompt);
547	
548	        if (decision.reasoningBudget === 'cheap') {
549	            return { response: draft, shouldEscalate: false, loopCount: 1 };
550	        }
551	
552	        const originalRequest = this.extractLastUserMessage(messages) || '';
553	        const critiquePrompt = [
554	            {
555	                role: 'user',
556	                content: [
557	                    'Evaluate the draft answer for missing constraints, contradictions, or low confidence.',
558	                    'Return strict JSON with keys:',
559	                    '{"confidence": number, "contradiction": boolean, "missingConstraints": string[], "shouldEscalate": boolean, "revisionBrief": string}',
560	                    '',
561	                    `ORIGINAL_REQUEST:\n${originalRequest}`,
562	                    '',
563	                    `DRAFT_RESPONSE:\n${draft.content}`
564	                ].join('\n')
565	            }
566	        ];
567	
568	        const critique = await this.executeOllamaChat(localModelName, critiquePrompt, finalSystemPrompt);
569	        const parsedCritique = this.extractJsonObject(critique.content);
570	
571	        if (!parsedCritique) {
572	            return {
573	                response: draft,
574	                shouldEscalate: true,
575	                fallbackCause: 'LOCAL_CRITIQUE_PARSE_FAILURE',
576	                loopCount: 2
577	            };
578	        }
579	
580	        const confidence = typeof parsedCritique.confidence === 'number' ? parsedCritique.confidence : 0;
581	        const contradiction = Boolean(parsedCritique.contradiction);
582	        const missingConstraints = Array.isArray(parsedCritique.missingConstraints)
583	            ? parsedCritique.missingConstraints
584	            : [];
585	        const shouldEscalate = Boolean(parsedCritique.shouldEscalate)
586	            || contradiction
587	            || confidence < 0.66
588	            || (missingConstraints.length > 0 && decision.risk !== 'low');
589	
590	        if (shouldEscalate) {
591	            return {
592	                response: draft,
593	                shouldEscalate: true,
594	                fallbackCause: 'LOCAL_LOW_CONFIDENCE',
595	                loopCount: 2
596	            };
597	        }
598	
599	        const revisedPrompt = [
600	            ...messages,
601	            { role: 'assistant', content: draft.content },
602	            {
603	                role: 'user',
604	                content: [
605	                    'Revise the previous answer using this critique summary.',
606	                    String(parsedCritique.revisionBrief || 'Tighten accuracy and keep the answer concise.')
607	                ].join('\n')
608	            }
609	        ];
610	
611	        const revised = await this.executeOllamaChat(localModelName, revisedPrompt, finalSystemPrompt);
612	        return {
613	            response: revised,
614	            shouldEscalate: false,
615	            loopCount: 3
616	        };
617	    }
